      "reps": "10-15",
      "sets": "3"
    },
    {
      "name": "Plank to Push-up",
      "description": "Start in a high plank position. Lower your body into a push-up position, then push back up to the plank. Focus on keeping the core tight.",
      "reps": "10-12",
      "sets": "3"
    },
    {
      name": "Fist to Push-up",
      "description": "Start in a high plank position. Bring your fists together in front of your chest, then extend your arms to perform a push-up. Repeat.",
      "reps": "10-12",
      "sets": "3"
    },
    {
      name": "Fist to Push-up (Reverse)",
      "description": "Start in a high plank position. Bring your fists together in front of your chest, then extend your arms to perform a push-up, but start with your hands in front of your chest and end with hands behind your head.",
      "reps": "10-12",
      "sets": "3"
    },
    {
      name": "Fist to Push-up (Reverse) - High to Low",
      "description": "Start in a high plank position. Bring your fists together in front of your chest, then extend your arms to perform a push-up, but start with your hands in front of your chest and end with hands behind your head, then lower your hands to the floor.",
